import { createValidationContext, resolveReference } from './ref.mjs';
import { assertSchemaNode, hasOwn } from './utils.mjs';
import { validateArrayKeywords } from './validators/array.mjs';
import { validateCombiningKeywords } from './validators/combiners.mjs';
import { validateObjectKeywords } from './validators/object.mjs';
import { validateScalarKeywords } from './validators/scalar.mjs';

function validateAgainstSchema(instance, schema, context) {
  assertSchemaNode(schema);

  if (typeof schema === 'boolean') {
    return schema ? 0 : 1;
  }

  if (hasOwn(schema, '$ref')) {
    return validateAgainstSchema(instance, resolveReference(schema.$ref, context), context);
  }

  const validate = (nextInstance, nextSchema) =>
    validateAgainstSchema(nextInstance, nextSchema, context);
  const isValid = (nextInstance, nextSchema) => validate(nextInstance, nextSchema) === 0;

  let errorCount = 0;
  errorCount += validateScalarKeywords(instance, schema);
  errorCount += validateObjectKeywords(instance, schema, validate);
  errorCount += validateArrayKeywords(instance, schema, validate, isValid);
  errorCount += validateCombiningKeywords(instance, schema, validate, isValid);

  return errorCount;
}

export function countValidationErrors(instance, schema) {
  assertSchemaNode(schema);
  const context = createValidationContext(schema);
  return validateAgainstSchema(instance, schema, context);
}

