export function hasOwn(objectValue, key) {
  return Object.prototype.hasOwnProperty.call(objectValue, key);
}

export function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function describePythonType(value) {
  if (typeof value === 'number') {
    return Number.isInteger(value) ? 'int' : 'float';
  }

  if (typeof value === 'string') {
    return 'str';
  }

  if (typeof value === 'boolean') {
    return 'bool';
  }

  if (Array.isArray(value)) {
    return 'list';
  }

  if (value === null) {
    return 'NoneType';
  }

  return 'dict';
}

export function assertSchemaNode(schema) {
  if (typeof schema === 'boolean' || isPlainObject(schema)) {
    return;
  }

  throw new TypeError(`argument of type '${describePythonType(schema)}' is not iterable`);
}

export function isJsonNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

export function isJsonInteger(value) {
  return isJsonNumber(value) && Number.isInteger(value);
}

export function unicodeLength(value) {
  return Array.from(value).length;
}

export function matchesType(instance, typeName) {
  switch (typeName) {
    case 'null':
      return instance === null;
    case 'boolean':
      return typeof instance === 'boolean';
    case 'object':
      return isPlainObject(instance);
    case 'array':
      return Array.isArray(instance);
    case 'number':
      return isJsonNumber(instance);
    case 'integer':
      return isJsonInteger(instance);
    case 'string':
      return typeof instance === 'string';
    default:
      return false;
  }
}

export function matchesDeclaredType(instance, declaredType) {
  if (typeof declaredType === 'string') {
    return matchesType(instance, declaredType);
  }

  if (Array.isArray(declaredType)) {
    return declaredType.some((typeName) => matchesType(instance, typeName));
  }

  return false;
}

export function jsonEquals(left, right) {
  if (left === right) {
    return true;
  }

  if (typeof left !== typeof right) {
    return false;
  }

  if (left === null || right === null) {
    return left === right;
  }

  if (Array.isArray(left)) {
    if (!Array.isArray(right) || left.length !== right.length) {
      return false;
    }

    for (let index = 0; index < left.length; index += 1) {
      if (!jsonEquals(left[index], right[index])) {
        return false;
      }
    }

    return true;
  }

  if (isPlainObject(left)) {
    if (!isPlainObject(right)) {
      return false;
    }

    const leftKeys = Object.keys(left);
    const rightKeys = Object.keys(right);
    if (leftKeys.length !== rightKeys.length) {
      return false;
    }

    for (const key of leftKeys) {
      if (!hasOwn(right, key) || !jsonEquals(left[key], right[key])) {
        return false;
      }
    }

    return true;
  }

  return false;
}

